const VLQ_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

export interface SessionSourceMap {
  version: 3;
  /** The transformed file first, then every other file a copy comes from. */
  sources: string[];
  names: string[];
  mappings: string;
  /** The text of each source, in the order of `sources`. */
  sourcesContent?: string[];
}

export interface ResolvedSessionConfig {
  root: string;
  options: ts.CompilerOptions;
  configPath: string;
  /** Text of the tsconfig and its extends chain. */
  contentStamp?: string;
}

/** Session map for one transformed file, plus the user's original text. */
export interface SessionFileMap {
  map: SessionSourceMap;
  originalText: string;
}

export interface SessionState {
  previousProgram?: ts.Program;
  cachedSources: Map<string, { stamp: string; source: ts.SourceFile }>;
  registeredTokens: Set<string>;
  usedTokens: Map<string, UsedTokenEntry>;
  generatedContainerVars: Set<string>;
  devtoolsGraphs: Map<string, SerializableGraph>;
  resolved?: ResolvedSessionConfig;
  graphs?: DependencyGraph[];
  graphProgram?: ts.Program;
  /** Project sources parsed on a cache miss. Not a package export. */
  filesParsed: number;
  /** Graphs produced by extractAll. A cache hit adds nothing. */
  graphsBuilt: number;
  /** Lib and declaration SourceFiles for this plugin instance only. */
  declarationSources: Map<string, { stamp: string; source: ts.SourceFile }>;
  /** One identity registry for every container generated by this session. */
  collisions?: CollisionRegistry;
  /**
   * Replaces the artifact hash. Tests use it to put two descriptors on one key.
   * Production leaves it unset.
   */
  artifactHash?: (descriptor: string) => string;
}

/** Test and bench handle for the SessionState closed over by one plugin instance. */
export const sessionStateKey: unique symbol = Symbol('neoSyringe.sessionState');

export interface SessionInput {
  code: string;
  id: string;
  project?: string;
  cwd: string;
  emitDebugHelpers: boolean;
  testOverrides: boolean;
  devtools: boolean;
  state: SessionState;
  errorPrefix: string;
  hostProgram?: ts.Program;
  hostSource?: ts.SourceFile;
}

export interface SessionOutput {
  code: string;
  map: SessionSourceMap | null;
}

/**
 * A range of an edit's text copied from one source. `gen` is where it starts in the edit text,
 * `orig` where it starts in the source, both in UTF-16 units. `source` is an index into the
 * `sources` of the map: 0 is the transformed file, the default.
 */
export interface MappedCopy {
  gen: number;
  orig: number;
  length: number;
  source?: number;
}

interface MappedEdit {
  start: number;
  end: number;
  text: string;
  copies?: MappedCopy[];
}

/** A source of a map other than the transformed file. */
export interface MapSource {
  name: string;
  text: string;
}

/**
 * Turns the copies a Generator rendered into the copies of an edit. `files` is the list of source
 * files of the map, the transformed file first; a file not in it yet is appended, so the order of
 * `files` is the order of first use. Positions stay UTF-16 offsets: the line and the column are
 * computed once the text of each source is known (`applyMappedEdits`).
 */
export function copiesToSegments(copies: readonly CopyMapping[], files: string[]): MappedCopy[] {
  return copies.map((copy) => {
    let source = files.indexOf(copy.sourceFile);
    if (source < 0) source = files.push(copy.sourceFile) - 1;
    return { gen: copy.generatedStart, orig: copy.sourceStart, length: copy.length, source };
  });
}

/**
 * The name of `file` in a map that names the transformed file `primaryName`, in the same path style:
 * the path from the directory of `primaryFile` to `file`, joined to the directory of `primaryName`.
 * An absolute name gives an absolute name, a name relative to a map gives a name relative to it.
 * A name written with backslashes only is answered with backslashes.
 */
export function siblingSourceName(primaryName: string, primaryFile: string, file: string): string {
  const posix = path.posix;
  const from = posix.dirname(normalizeModuleId(primaryFile));
  const name = posix.join(posix.dirname(normalizeModuleId(primaryName)), posix.relative(from, file.replace(/\\/g, '/')));
  return primaryName.includes('\\') && !primaryName.includes('/') ? name.replace(/\//g, '\\') : name;
}

/** `\` → `/`, then drop `?query` and `#hash`. */
export function normalizeModuleId(id: string): string {
  const hash = id.indexOf('#');
  const noHash = hash === -1 ? id : id.slice(0, hash);
  const query = noHash.indexOf('?');
  const noQuery = query === -1 ? noHash : noHash.slice(0, query);
  return noQuery.replace(/\\/g, '/');
}

/** Extension of `id` before a query is removed. `.ts?v=1` is not `.ts`. */
function rawExtension(id: string): string {
  const hash = id.indexOf('#');
  const noHash = hash === -1 ? id : id.slice(0, hash);
  const slash = Math.max(noHash.lastIndexOf('/'), noHash.lastIndexOf('\\'));
  const dot = noHash.lastIndexOf('.');
  if (dot <= slash) return '';
  return noHash.slice(dot).toLowerCase();
}

/**
 * Name stored on the SourceFile.
 * An id whose own text ends in `.ts` or `.tsx` keeps its query (`App.vue?lang.ts`).
 * A query that merely follows a `.ts` path (`a.ts?v=1`) is removed.
 */
export function programFileName(id: string): string {
  const hash = id.indexOf('#');
  const noHash = hash === -1 ? id : id.slice(0, hash);
  const ext = rawExtension(noHash);
  if (ext === '.ts' || ext === '.tsx') return noHash.replace(/\\/g, '/');
  return normalizeModuleId(id);
}

export function moduleExtension(id: string): string {
  const ext = rawExtension(id);
  if (ext === '.ts' || ext === '.tsx' || ext === '.mts' || ext === '.cts') return ext;
  const base = normalizeModuleId(id);
  const slash = base.lastIndexOf('/');
  const dot = base.lastIndexOf('.');
  if (dot <= slash) return '';
  return base.slice(dot).toLowerCase();
}

export function shouldTransformId(id: string): boolean {
  const ext = moduleExtension(id);
  return ext === '.ts' || ext === '.tsx' || ext === '.mts' || ext === '.cts';
}

function vlq(value: number): string {
  let n = value < 0 ? ((-value) << 1) + 1 : value << 1;
  let encoded = '';
  for (;;) {
    let digit = n & 31;
    n >>>= 5;
    if (n > 0) digit |= 32;
    encoded += VLQ_CHARS[digit];
    if (n === 0) return encoded;
  }
}

/** LF, CR, U+2028 and U+2029 end a line; CR LF is one line end (the LF ends it). */
function isLineEnd(code: number): boolean {
  return code === 10 || code === 13 || code === 0x2028 || code === 0x2029;
}

function lineStartsOf(code: string): number[] {
  const starts = [0];
  for (let i = 0; i < code.length; i += 1) {
    const char = code.charCodeAt(i);
    if (!isLineEnd(char)) continue;
    if (char === 13 && code.charCodeAt(i + 1) === 10) continue;
    starts.push(i + 1);
  }
  return starts;
}

function positionAt(starts: number[], offset: number): { line: number; column: number } {
  let low = 0;
  let high = starts.length - 1;
  while (low < high) {
    const mid = (low + high + 1) >> 1;
    if (starts[mid] <= offset) low = mid;
    else high = mid - 1;
  }
  return { line: low, column: offset - starts[low] };
}

function isWordChar(code: number): boolean {
  return (code >= 48 && code <= 57)
    || (code >= 65 && code <= 90)
    || (code >= 97 && code <= 122)
    || code === 36
    || code === 95;
}

/** Line start, copy/generated boundary, or the first character of a word. */
function mappedSegment(lineStart: boolean, boundary: boolean, wordChar: boolean, prevWord: boolean): boolean {
  if (lineStart || boundary) return true;
  return wordChar && !prevWord;
}

function copiedOrigin(from: number, index: number): number {
  return from + index;
}

function encodeMappings(
  segments: readonly { genLine: number; genCol: number; orig: number; source: number }[],
  texts: readonly string[],
): string {
  const starts = texts.map(lineStartsOf);
  let prevGenCol = 0;
  let prevSource = 0;
  let prevSrcLine = 0;
  let prevSrcCol = 0;
  let line = 0;
  const groups: string[][] = [[]];
  for (const segment of segments) {
    while (line < segment.genLine) {
      line += 1;
      groups.push([]);
      prevGenCol = 0;
    }
    const pos = positionAt(starts[segment.source], segment.orig);
    groups[line].push(
      vlq(segment.genCol - prevGenCol) +
      vlq(segment.source - prevSource) +
      vlq(pos.line - prevSrcLine) +
      vlq(pos.column - prevSrcCol),
    );
    prevGenCol = segment.genCol;
    prevSource = segment.source;
    prevSrcLine = pos.line;
    prevSrcCol = pos.column;
  }
  return groups.map((group) => group.join(',')).join(';');
}

/**
 * Applies edits on the original text and emits one v3 map.
 * Segments sit on line starts, copy boundaries and word starts.
 * trace-mapping does not interpolate columns, so a word start keeps its column.
 * A copy may come from another file: `extras` are the sources 1, 2, ... of the map. A copy that
 * names a source the map does not have is not mapped.
 */
export function applyMappedEdits(
  code: string,
  edits: readonly MappedEdit[],
  sourceName: string,
  extras: readonly MapSource[] = [],
): { code: string; map: SessionSourceMap } {
  const sorted = edits
    .filter((edit) => edit.start >= 0 && edit.end >= edit.start && edit.start <= code.length)
    .map((edit) => ({ ...edit, end: Math.min(edit.end, code.length) }))
    .sort((a, b) => a.start - b.start || b.end - a.end);
  const chosen: MappedEdit[] = [];
  let cursor = 0;
  for (const edit of sorted) {
    if (edit.start < cursor) continue;
    chosen.push(edit);
    cursor = edit.end;
  }

  const parts: string[] = [];
  const segments: { genLine: number; genCol: number; orig: number; source: number }[] = [];
  let genLine = 0;
  let genCol = 0;
  let mappedBefore = false;
  let prevWord = false;
  // A CR already ended its line: the LF right after it, even in the next piece, ends nothing more.
  let afterCr = false;
  const emit = (text: string, from: { source: number; at: (index: number) => number } | null): void => {
    // Reset before the empty check: an empty generated text between two copies still ends the first one.
    if (from === null) mappedBefore = false;
    if (text.length === 0) return;
    for (let index = 0; index < text.length; index += 1) {
      const codePoint = text.charCodeAt(index);
      if (isLineEnd(codePoint)) {
        if (codePoint === 10 && afterCr) {
          afterCr = false;
          continue;
        }
        afterCr = codePoint === 13;
        genLine += 1;
        genCol = 0;
        mappedBefore = false;
        prevWord = false;
        continue;
      }
      afterCr = false;
      const origin = from === null ? -1 : from.at(index);
      const mapped = origin >= 0;
      // The first character of a copy starts a segment, whatever the copy before it was (same place, other
      // place, other source): every copy is preceded by an `emit(..., null)` that cleared `mappedBefore`.
      if (from !== null && mapped && mappedSegment(genCol === 0, !mappedBefore, isWordChar(codePoint), prevWord)) {
        segments.push({ genLine, genCol, orig: origin, source: from.source });
      }
      mappedBefore = mapped;
      prevWord = isWordChar(codePoint);
      genCol += 1;
    }
    parts.push(text);
  };
  const emitReplacement = (edit: MappedEdit): void => {
    const copies = [...(edit.copies ?? [])].sort((a, b) => a.gen - b.gen);
    let at = 0;
    for (const copy of copies) {
      const source = copy.source ?? 0;
      if (copy.gen < at || copy.length <= 0 || source < 0 || source > extras.length) continue;
      emit(edit.text.slice(at, copy.gen), null);
      const length = Math.min(copy.length, edit.text.length - copy.gen);
      emit(edit.text.slice(copy.gen, copy.gen + length), { source, at: (index) => copiedOrigin(copy.orig, index) });
      at = copy.gen + length;
    }
    emit(edit.text.slice(at), null);
  };

  let from = 0;
  for (const edit of chosen) {
    const kept = from;
    emit(code.slice(kept, edit.start), { source: 0, at: (index) => copiedOrigin(kept, index) });
    emitReplacement(edit);
    from = edit.end;
  }
  const tail = from;
  emit(code.slice(tail), { source: 0, at: (index) => copiedOrigin(tail, index) });
  const edited = parts.join('');
  return {
    code: edited,
    map: {
      version: 3,
      sources: [sourceName, ...extras.map((extra) => extra.name)],
      names: [],
      mappings: encodeMappings(segments, [code, ...extras.map((extra) => extra.text)]),
      sourcesContent: [code, ...extras.map((extra) => extra.text)],
    },
  };
}

/** Excludes TS18003 (no input files). Joins the remaining diagnostic messages. */
export function blockingConfigMessage(
  diagnostics: readonly ts.Diagnostic[],
  tsInstance: typeof ts,
): string | undefined {
  const blocking = diagnostics.filter((diagnostic) => diagnostic.code !== 18003);
  if (blocking.length === 0) return undefined;
  return blocking
    .map((diagnostic) => tsInstance.flattenDiagnosticMessageText(diagnostic.messageText, '\n'))
    .join('\n  ');
}

function resolveCached(input: SessionInput): ResolvedSessionConfig {
  const previous = input.state.resolved;
  const abs = input.project
    ? path.resolve(input.cwd, input.project)
    : ts.findConfigFile(input.cwd, ts.sys.fileExists, 'tsconfig.json');
  let knownChain: string | undefined;
  if (abs && previous && previous.configPath === abs) {
    const chain = configChainTexts(abs);
    if (previous.contentStamp === chain) return previous;
    knownChain = chain;
  }
  const resolved = resolveProjectConfig(input.cwd, input.project);
  const messages = blockingConfigMessage(resolved.parseErrors, ts);
  if (messages !== undefined) {
    throw new Error(`${input.errorPrefix}\n  ${messages}`);
  }
  if (previous) {
    // registeredTokens and usedTokens stay. They belong to the build, not to this tsconfig.
    input.state.previousProgram = undefined;
    input.state.cachedSources = new Map();
    input.state.graphs = undefined;
    input.state.graphProgram = undefined;
  }
  const chain = knownChain !== undefined && resolved.configPath === abs
    ? knownChain
    : configChainTexts(resolved.configPath);
  const stored: ResolvedSessionConfig = {
    root: resolved.root,
    options: resolved.options,
    configPath: resolved.configPath,
    contentStamp: chain,
  };
  input.state.resolved = stored;
  return stored;
}

function rejectUnsupportedMarkers(sourceFile: ts.SourceFile, checker: ts.TypeChecker): void {
  const visit = (node: ts.Node): void => {
    if (ts.isCallExpression(node)) {
      const marker = resolveNeoMarker(checker, node);
      if (marker && typeof marker === 'object') {
        throw new Error(formatUnsupportedMarker(node));
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
}

function visitServices(graph: DependencyGraph, visit: (node: DependencyNode) => void): void {
  for (const node of graph.nodes.values()) visit(node);
  if (!graph.multiNodes) return;
  for (const nodes of graph.multiNodes.values()) {
    for (const node of nodes) visit(node);
  }
}

/** Use-site edits of one foreign file, walked once per compileWith call. */
function cachedForeignUseEdits(
  sourceFile: ts.SourceFile,
  checker: ts.TypeChecker,
  usedTokens: Map<string, UsedTokenEntry>,
  cache: Map<ts.SourceFile, readonly SourceEdit[]>,
): readonly SourceEdit[] {
  const cached = cache.get(sourceFile);
  if (cached) return cached;
  const collected = collectUseSiteEdits(sourceFile, checker, usedTokens);
  cache.set(sourceFile, collected);
  return collected;
}

/**
 * The edits that sit entirely inside `origin`, as rewrites of that range. A use-site call inside a
 * provider or a useValue is one of them: the generator writes its text, and copies the rest.
 */
export function rewritesIn(origin: SourceOrigin, edits: readonly SourceEdit[]): SourceRewrite[] {
  const end = origin.start + origin.length;
  return edits
    .filter((edit) => edit.start >= origin.start && edit.end <= end)
    .map(({ start, end: stop, text }) => ({ start, end: stop, text }))
    .sort((left, right) => left.start - right.start || left.end - right.end);
}

/**
 * Carries the use-site rewrites of a provider or a useValue on the graph, as data next to its origin.
 * `factorySource` and `valueSource` keep the original text: the copy is still a copy.
 * A registration that lives in another file is rewritten from the edits of that file.
 */
export function attachRewrites(
  graph: DependencyGraph,
  sourceFile: ts.SourceFile,
  edits: readonly SourceEdit[],
  checker: ts.TypeChecker,
  usedTokens: Map<string, UsedTokenEntry>,
  foreignEdits: Map<ts.SourceFile, readonly SourceEdit[]>,
): void {
  visitServices(graph, (node) => {
    const { service } = node;
    const origin = service.type === 'factory' ? service.factoryOrigin : service.type === 'value' ? service.valueOrigin : undefined;
    if (!origin || !service.registrationNode) return;
    const registrationFile = service.registrationNode.getSourceFile();
    if (registrationFile.fileName !== origin.file) return;
    const fileEdits = registrationFile === sourceFile
      ? edits
      : cachedForeignUseEdits(registrationFile, checker, usedTokens, foreignEdits);
    const rewrites = rewritesIn(origin, fileEdits);
    if (rewrites.length === 0) return;
    if (service.type === 'factory') service.factoryRewrites = rewrites;
    else service.valueRewrites = rewrites;
  });
}

/**
 * The texts the generators copy from, read from the analysis Program, once for every container of a
 * file. Only the files the graphs name as an origin are held: the id is a hash of what is held, and a
 * Program holds thousands of files nobody copies from. A file the Program does not hold is left out:
 * a generator copies nothing from a file the snapshot lacks, it never reads the text from elsewhere.
 */
export function analysisSnapshot(graphs: readonly DependencyGraph[], program: ts.Program): Snapshot {
  const files = new Map<string, string>();
  const read = (file: string): void => {
    if (files.has(file)) return;
    const text = program.getSourceFile(file)?.text;
    if (text !== undefined) files.set(file, text);
  };
  for (const graph of graphs) {
    visitServices(graph, (node) => {
      for (const origin of [node.service.factoryOrigin, node.service.valueOrigin]) {
        if (origin) read(origin.file);
      }
    });
  }
  return snapshotOfFiles(files);
}

function isProjectParse(fileName: string, root: string): boolean {
  const canon = canonicalPath(fileName);
  const base = canonicalPath(root).replace(/\/$/, '');
  if (canon !== base && !canon.startsWith(`${base}/`)) return false;
  return !canon.endsWith('.d.ts') && !canon.endsWith('.d.mts') && !canon.endsWith('.d.cts');
}

function rememberSource(
  state: SessionState,
  fileName: string,
  sourceText: string,
  projectRoot: string | undefined,
): ts.SourceFile {
  const canon = canonicalPath(fileName);
  const cached = state.cachedSources.get(fileName) ?? state.cachedSources.get(canon);
  if (cached && cached.stamp === sourceText) {
    state.cachedSources.set(fileName, cached);
    return cached.source;
  }
  const created = ts.createSourceFile(fileName, sourceText, ts.ScriptTarget.Latest, true);
  const stored = { stamp: sourceText, source: created };
  state.cachedSources.set(fileName, stored);
  state.cachedSources.set(canon, stored);
  if (projectRoot && isProjectParse(fileName, projectRoot)) noteFileParsed(state);
  return created;
}

/** The errors that stop a transform. Warnings and resolve-call checks do not. */
function blockingErrors(errors: readonly AnalysisError[]): AnalysisError[] {
  return errors.filter((error) => stableSeverityOf(error) === 'error' && !isResolutionUsageError(error));
}

/** A failure the graphs of a file report, with the wording the build has always printed for it. */
interface GraphFailure {
  code: string;
  node: ts.Node;
  sourceFile: ts.SourceFile;
  /** The dependency a missing provider names. */
  dependency?: string;
  message: string;
}

/**
 * What the graphs of this file report: their own errors, then the ones of GraphValidator. The wording is
 * pinned by tests/e2e/t08-child-all-open-parent.test.ts:257 and tests/e2e/t20-docs-examples.test.ts:1009:
 * the token name ('Needs', GraphValidator.ts:83), a final dot.
 */
function graphFailures(sameFile: readonly DependencyGraph[], validated: readonly DependencyGraph[]): GraphFailure[] {
  const found: GraphFailure[] = [];
  for (const graph of sameFile) {
    for (const error of graph.errors ?? []) {
      found.push({
        code: stableCodeOf(error) ?? error.type,
        node: error.node,
        sourceFile: error.sourceFile,
        dependency: error.context?.tokenText,
        message: error.message,
      });
    }
  }
  const validator = new GraphValidator();
  for (const graph of validated) {
    for (const error of validator.validateAll(graph).errors) {
      found.push({
        code: error.code ?? (error.type === 'duplicate' ? 'NEO_DUPLICATE_PROVIDER' : error.type),
        node: error.node,
        sourceFile: error.sourceFile,
        dependency: error.dependencyId,
        message: error.message,
      });
    }
  }
  return found;
}

/** The two nodes are one registration: one holds the other (the graph anchors the injection, the snapshot its token). */
function nestedNodes(left: ts.Node, leftFile: ts.SourceFile, right: ts.Node, rightFile: ts.SourceFile): boolean {
  const leftStart = left.getStart(leftFile);
  const rightStart = right.getStart(rightFile);
  return (leftStart >= rightStart && left.getEnd() <= right.getEnd())
    || (rightStart >= leftStart && right.getEnd() <= left.getEnd());
}

/**
 * One line per blocking snapshot error. The text of the graph is kept for an error the graph reports too:
 * same code, same file, same registration, same dependency. Each graph failure words one error at most.
 * An error the graph does not report keeps the text of the snapshot, so none is hidden.
 */
function blockingMessages(errors: readonly AnalysisError[], failures: readonly GraphFailure[]): string[] {
  const unused = [...failures];
  return errors.map((error) => {
    const code = stableCodeOf(error) ?? error.type;
    const wanted = error.context?.tokenText;
    const at = unused.findIndex((failure) =>
      failure.code === code
      && failure.sourceFile.fileName === error.sourceFile.fileName
      && (failure.dependency === undefined || wanted === undefined || failure.dependency === wanted)
      && nestedNodes(failure.node, failure.sourceFile, error.node, error.sourceFile));
    if (at < 0) return error.message;
    const [match] = unused.splice(at, 1);
    return match?.message ?? error.message;
  });
}

/** What the GraphValidator throw carries as analysis errors: the same fields, the code of a missing provider and of a cycle. */
function analysisErrorsOfValidation(errors: readonly GraphValidationError[]): AnalysisError[] {
  return errors.map((error) => ({
    type: error.type,
    ...(error.code !== undefined ? { code: error.code } : {}),
    message: error.message,
    node: error.node,
    sourceFile: error.sourceFile,
    ...(error.dependencyId !== undefined ? { context: { tokenText: error.dependencyId } } : {}),
  }));
}

function compileWith(input: SessionInput, resolved: ResolvedSessionConfig | undefined): SessionOutput {
  const key = programFileName(input.id);
  if (!input.hostProgram && !callsCanReachNeoSyringe(input.code, key, resolved?.options ?? {})) {
    return { code: input.code, map: null };
  }
  let program = input.hostProgram;
  if (!program) {
    const options = resolved?.options ?? {};
    const projectRoot = resolved?.root;
    const norm = (fileName: string) => fileName.replace(/\\/g, '/');
    const compilerHost: ts.CompilerHost = {
      getSourceFile: (fileName) => {
        const isEntry = norm(fileName) === key || canonicalPath(fileName) === canonicalPath(key);
        if (isEntry) return rememberSource(input.state, fileName, input.code, projectRoot);
        try {
          const sourceText = ts.sys.readFile(fileName);
          if (!sourceText) return undefined;
          return rememberSource(input.state, fileName, sourceText, projectRoot);
        } catch {
          return undefined;
        }
      },
      getDefaultLibFileName: (opts) => ts.getDefaultLibFileName(opts),
      writeFile: () => {},
      getCurrentDirectory: () => input.cwd,
      getDirectories: (dir) => ts.sys.getDirectories(dir),
      fileExists: (fileName) => {
        if (norm(fileName) === key) return true;
        return ts.sys.fileExists(fileName);
      },
      readFile: (fileName) => {
        if (norm(fileName) === key) return input.code;
        return ts.sys.readFile(fileName);
      },
      getCanonicalFileName: (fileName) => fileName,
      useCaseSensitiveFileNames: () => ts.sys.useCaseSensitiveFileNames,
      getNewLine: () => '\n',
    };
    program = ts.createProgram([key], options, compilerHost, input.state.previousProgram);
    input.state.previousProgram = program;
  }

  const checker = program.getTypeChecker();
  const sourceFile = input.hostSource
    ?? (typeof program.getSourceFile === 'function' ? program.getSourceFile(key) ?? program.getSourceFile(input.id) : undefined);
  if (
    sourceFile &&
    typeof checker.getSymbolAtLocation === 'function' &&
    !sourceFileUsesMarker(checker, sourceFile)
  ) {
    return { code: input.code, map: null };
  }
  if (sourceFile && typeof checker.getSymbolAtLocation === 'function') {
    rejectUnsupportedMarkers(sourceFile, checker);
  }

  // Same host program object: the files cannot have changed inside this call.
  let allGraphs: DependencyGraph[];
  if (input.hostProgram && input.state.graphProgram === program && input.state.graphs) {
    allGraphs = input.state.graphs.map(cloneGraph);
  } else {
    allGraphs = graphsForProgram(
      input.state,
      () => new Analyzer(program).extractAll(),
      input.hostProgram,
    );
  }

  const sameFileGraphs = allGraphs.filter((graph) => (graph.sourceFileName ?? key).replace(/\\/g, '/') === key);
  const thisFileGraphs = sameFileGraphs.filter((graph) =>
    graph.defineBuilderConfigStart !== undefined &&
    graph.defineBuilderConfigEnd !== undefined &&
    graph.variableStatementStart !== undefined);

  // The diagnostics of this file come from the same snapshot as the graphs, so the build reports
  // what the CLI and the IDE report. A resolve call is checked once every file is known (buildEnd).
  // The text keeps the wording the build has always printed when the graph says the same thing.
  const fileErrors = sourceFile ? blockingErrors(new Analyzer(program).extractForFile(sourceFile.fileName).errors) : [];
  if (fileErrors.length > 0) {
    const messages = blockingMessages(fileErrors, graphFailures(sameFileGraphs, thisFileGraphs))
      .map((message) => `${input.errorPrefix} ${message}`)
      .join('\n');
    const buildError = new Error(messages) as Error & { file?: string; analysisErrors?: AnalysisError[] };
    buildError.name = fileErrors[0].type === 'duplicate' ? 'DuplicateRegistrationError' : 'TypeMismatchError';
    buildError.file = input.id;
    buildError.analysisErrors = fileErrors;
    throw buildError;
  }

  for (const graph of allGraphs) {
    for (const tokenId of graph.nodes.keys()) input.state.registeredTokens.add(tokenId);
    if (graph.multiNodes) {
      for (const tokenId of graph.multiNodes.keys()) input.state.registeredTokens.add(tokenId);
    }
    if (graph.parentProvidedTokens) {
      for (const tokenId of graph.parentProvidedTokens) input.state.registeredTokens.add(tokenId);
    }
  }

  if (thisFileGraphs.length > 0) {
    const validator = new GraphValidator();
    for (const graph of thisFileGraphs) {
      const validationResult = validator.validateAll(graph);
      if (!validationResult.valid) {
        const messages = validationResult.errors.map((error) => error.message).join('\n  ');
        const buildError = new Error(`${input.errorPrefix}\n  ${messages}`) as Error & { file?: string; analysisErrors?: AnalysisError[] };
        buildError.file = input.id;
        buildError.analysisErrors = analysisErrorsOfValidation(validationResult.errors);
        throw buildError;
      }
    }
  }

  const pureEdits: SourceEdit[] = [];
  const useEdits: SourceEdit[] = [];
  if (sourceFile && typeof checker.getSymbolAtLocation === 'function') {
    pureEdits.push(...collectDefinePartialConfigPureEdits(sourceFile, checker));
    useEdits.push(...collectUseSiteEdits(sourceFile, checker, input.state.usedTokens));
  }

  const foreignEdits = new Map<ts.SourceFile, readonly SourceEdit[]>();
  const edits: MappedEdit[] = [];
  if (thisFileGraphs.length > 0) {
    if (!input.state.collisions) input.state.collisions = new CollisionRegistry();
    input.state.collisions.bind(key);
  }
  // One pool per source file and per call: the containers of this file are written into the same
  // scope, so their generated names must not collide with each other or with a name the file declares.
  // The checker holds the bindings of the file (a `var` hoisted out of a block included).
  const names = new NamePool(
    sourceFile ? reservedNamesOf(sourceFile, checker) : [],
  );
  // The texts every container of this file copies from. The first source of the map is this file.
  const snapshot = analysisSnapshot(thisFileGraphs, program);
  const mapFiles: string[] = [sourceFile?.fileName ?? key];
  for (const graph of thisFileGraphs) {
    if (sourceFile) attachRewrites(graph, sourceFile, useEdits, checker, input.state.usedTokens, foreignEdits);
    const generator = new Generator(
      graph,
      true,
      undefined,
      input.emitDebugHelpers,
      input.testOverrides,
      undefined,
      { collisions: input.state.collisions, hash: input.state.artifactHash },
      { names, snapshot },
    );
    const rendered = generator.generateRendered();
    const containerClass = rendered.code;
    const instantiation = generator.generateInstantiation();
    const start = graph.variableStatementStart!;
    const end = graph.defineBuilderConfigEnd!;
    const varDecl = input.code.slice(start, graph.defineBuilderConfigStart!);
    const text = containerClass + '\n' + varDecl + instantiation;
    // The generator says where each user expression was copied from; the class text starts the edit text.
    const copies: MappedCopy[] = copiesToSegments(rendered.copies, mapFiles);
    if (varDecl.length > 0) {
      copies.push({ gen: containerClass.length + 1, orig: start, length: varDecl.length });
    }
    edits.push({ start, end, text, copies });
    if (graph.exportedVariableName) input.state.generatedContainerVars.add(graph.exportedVariableName);
  }

  if (sourceFile && typeof checker.getSymbolAtLocation === 'function') {
    const ranges = edits.map((edit) => ({ start: edit.start, end: edit.end }));
    const outside = (offset: number) => !ranges.some((range) => offset >= range.start && offset < range.end);
    for (const edit of pureEdits) {
      if (outside(edit.start)) edits.push(edit);
    }
    for (const edit of useEdits) {
      if (outside(edit.start)) edits.push(edit);
    }
  }

  if (input.devtools) {
    const fileKey = programFileName(input.id);
    for (const [graphKey, stored] of input.state.devtoolsGraphs) {
      if ((stored.sourceFileName ?? '').replace(/\\/g, '/') === fileKey) {
        input.state.devtoolsGraphs.delete(graphKey);
      }
    }
    for (const graph of thisFileGraphs) {
      const graphKey = graph.containerKey ?? `${fileKey}:${graph.defineBuilderConfigStart}`;
      input.state.devtoolsGraphs.set(graphKey, serializeGraph(graph));
    }
  }

  if (edits.length === 0) return { code: input.code, map: null };
  // The other files a copy comes from are sources 1, 2, ... of this map. The ts transformer emit
  // (`composeMapText`) and the plugin map carry them. A Rollup or Vite build keeps only source 0 of a
  // transform map (rollup@4.55.2 node-entry.js:20304 builds `new Link(map, [source])`, :20228-20230 skips
  // the other indexes), so there a stack frame in a factory of another file maps to the neighbouring
  // segment of this file. Known limit, pinned by "T23-P6 known limit" in t23-provenance.test.ts.
  const extras: MapSource[] = mapFiles.slice(1).map((file) => ({
    name: siblingSourceName(input.id, mapFiles[0], file),
    text: snapshot.files.get(file) ?? '',
  }));
  const edited = applyMappedEdits(input.code, edits, input.id, extras);
  return { code: edited.code, map: edited.map };
}

export function runCompilationSession(input: SessionInput): SessionOutput {
  if (input.hostProgram && !input.project) {
    const configFilePath = input.hostProgram.getCompilerOptions().configFilePath;
    if (typeof configFilePath !== 'string') return compileWith(input, undefined);
    return TSContext.runWithProjectRoot(path.dirname(configFilePath), () => compileWith(input, undefined));
  }
  const resolved = resolveCached(input);
  return TSContext.runWithProjectRoot(resolved.root, () => compileWith(input, resolved));
}

interface EmittedSourceMap {
  version: 3;
  file?: string;
  sourceRoot?: string;
  sources?: (string | null)[];
  sourcesContent?: (string | null)[];
  names?: string[];
  mappings?: string;
}

/**
 * Composes an emitted `.js` or `.js.map` with the session map
 * (generated JS → transformed TS → original TS).
 * `.d.ts` and `.d.ts.map` are left untouched, so `declarationMap` still points
 * at the transformed text. `.tsbuildinfo` is not rewritten either: an
 * incremental host keeps the transformed text.
 */
export function rewriteEmittedOutput(
  fileName: string,
  text: string,
  sourceFiles: readonly { fileName: string }[] | undefined,
  sessions: ReadonlyMap<string, SessionFileMap>,
): string {
  if (fileName.endsWith('.d.ts') || fileName.endsWith('.d.ts.map')) return text;
  if (fileName.endsWith('.js.map')) return composeMapText(text, sourceFiles, sessions);
  if (fileName.endsWith('.js')) return composeInlineMap(text, sourceFiles, sessions);
  return text;
}

function composeInlineMap(
  text: string,
  sourceFiles: readonly { fileName: string }[] | undefined,
  sessions: ReadonlyMap<string, SessionFileMap>,
): string {
  const match = text.match(/((?:\/\/[#@]|\/\*#)[ \t]*sourceMappingURL=data:application\/json(?:;charset=utf-8)?;base64,)([A-Za-z0-9+/=]+)/);
  if (!match || match.index === undefined) return text;
  let json: string;
  try {
    json = Buffer.from(match[2], 'base64').toString('utf8');
  } catch {
    return text;
  }
  const composed = composeMapText(json, sourceFiles, sessions);
  if (composed === json) return text;
  const encoded = Buffer.from(composed, 'utf8').toString('base64');
  return text.slice(0, match.index) + match[1] + encoded + text.slice(match.index + match[0].length);
}

function composeMapText(
  text: string,
  sourceFiles: readonly { fileName: string }[] | undefined,
  sessions: ReadonlyMap<string, SessionFileMap>,
): string {
  let emitted: EmittedSourceMap;
  try {
    emitted = JSON.parse(text) as EmittedSourceMap;
  } catch {
    return text;
  }
  if (emitted.version !== 3 || typeof emitted.mappings !== 'string') return text;
  const sources = emitted.sources ?? [];
  const bound = bindSessions(sources, sourceFiles, sessions);
  if (!bound.some((record) => record)) return text;

  const tracers = new Map<SessionFileMap, TraceMap>();
  const tracerFor = (record: SessionFileMap): TraceMap => {
    const cached = tracers.get(record);
    if (cached) return cached;
    const created = new TraceMap(record.map);
    tracers.set(record, created);
    return created;
  };

  const nextContent = emitted.sourcesContent ? emitted.sourcesContent.slice() : undefined;
  if (nextContent) {
    for (let index = 0; index < nextContent.length; index += 1) {
      const record = bound[index];
      if (record && nextContent[index] != null) nextContent[index] = record.originalText;
    }
  }

  // A copy from another file adds a source to the emitted map, once per file, named like the
  // transformed file is (same directory style as its entry in `sources`).
  const outSources: (string | null)[] = [...sources];
  const extraSources = new Map<SessionFileMap, Map<number, number>>();
  const extraIndexOf = (record: SessionFileMap, sessionIndex: number, primaryIndex: number): number => {
    const known = extraSources.get(record) ?? new Map<number, number>();
    extraSources.set(record, known);
    const existing = known.get(sessionIndex);
    if (existing !== undefined) return existing;
    const primaryName = sources[primaryIndex];
    const file = record.map.sources[sessionIndex];
    const created = outSources.length;
    outSources.push(primaryName == null
      ? file
      : siblingSourceName(primaryName, record.map.sources[0], file));
    if (nextContent) nextContent.push(record.map.sourcesContent?.[sessionIndex] ?? null);
    known.set(sessionIndex, created);
    return created;
  };

  const decoded = decodedMappings(new TraceMap({
    version: 3,
    file: emitted.file,
    names: emitted.names ?? [],
    sources,
    sourcesContent: emitted.sourcesContent,
    mappings: emitted.mappings,
  }));
  const mappings: SourceMapSegment[][] = decoded.map((row) => {
    const next: SourceMapSegment[] = [];
    for (const segment of row) {
      const generatedColumn = segment[0];
      const sourceIndex = segment[1];
      const sourceLine = segment[2];
      const sourceColumn = segment[3];
      const nameIndex = segment[4];
      if (sourceIndex === undefined || sourceLine === undefined || sourceColumn === undefined) {
        next.push([generatedColumn]);
        continue;
      }
      const record = bound[sourceIndex];
      if (!record) {
        next.push(nameIndex === undefined
          ? [generatedColumn, sourceIndex, sourceLine, sourceColumn]
          : [generatedColumn, sourceIndex, sourceLine, sourceColumn, nameIndex]);
        continue;
      }
      // Copied columns outside the container are word-start granular.
      // The session map records word starts, and trace-mapping does not fill the gap.
      const tracer = tracerFor(record);
      const pos = originalPositionFor(tracer, { line: sourceLine + 1, column: sourceColumn });
      if (pos.line == null || pos.column == null) continue;
      const composedLine = pos.line - 1;
      const composedColumn = pos.column;
      const sessionIndex = pos.source == null ? 0 : Math.max(0, tracer.resolvedSources.indexOf(pos.source));
      const composedSource = sessionIndex === 0 ? sourceIndex : extraIndexOf(record, sessionIndex, sourceIndex);
      next.push(nameIndex === undefined
        ? [generatedColumn, composedSource, composedLine, composedColumn]
        : [generatedColumn, composedSource, composedLine, composedColumn, nameIndex]);
    }
    return next;
  });

  const encoded = encodedMappings(new TraceMap({
    version: 3,
    file: emitted.file,
    names: emitted.names ?? [],
    sources: outSources,
    sourcesContent: nextContent,
    mappings,
  }));
  const output: EmittedSourceMap = {
    version: 3,
    file: emitted.file,
    sources: outSources,
    names: emitted.names ?? [],
    mappings: encoded,
  };
  if (emitted.sourceRoot !== undefined) output.sourceRoot = emitted.sourceRoot;
  if (nextContent) output.sourcesContent = nextContent;
  return JSON.stringify(output);
}

function bindSessions(
  sources: readonly (string | null)[],
  sourceFiles: readonly { fileName: string }[] | undefined,
  sessions: ReadonlyMap<string, SessionFileMap>,
): (SessionFileMap | undefined)[] {
  if (sourceFiles && sourceFiles.length === sources.length) {
    return sourceFiles.map((file) => sessions.get(file.fileName));
  }
  return sources.map((): SessionFileMap | undefined => undefined);
}
